static int failures=0;
#define CHECK(x) do{if(!(x)){std::cerr<<"FAIL "<<__LINE__<<": " #x " ("<<error<<")\n";++failures;}}while(0)
static studio::DigitizeSource source(){studio::DigitizeSource f;f.label="JOB";f.w=f.h=32;f.rgba.assign(32*32*4,255);for(int y=4;y<28;++y)for(int x=4;x<28;++x){auto p=f.rgba.data()+(y*32+x)*4;p[0]=(unsigned char)(80+y*4);p[1]=p[2]=0;}return f;}
static bool wait(studio::DigitizeJob &job){auto start=std::chrono::steady_clock::now();while(!job.finished.load(std::memory_order_acquire)){if(std::chrono::steady_clock::now()-start>std::chrono::seconds(10)){job.cancel=true;return false;}std::this_thread::sleep_for(std::chrono::milliseconds(1));}return true;}
static void configure(studio::DigitizeJob &job,const studio::DigitizeSession &s,studio::DigitizeJobKind kind){job.kind=kind;job.owner=7;job.generation=11;job.epoch=13;job.input=std::make_unique<studio::DigitizeSession>(s);}
int main(){using namespace studio;namespace fs=std::filesystem;std::string error;auto art=Artwork::demo();DigitizeSession raw;CHECK(initialize_digitize({source(),source()},raw,error));auto sync=raw;CHECK(rebuild_digitize_matte(sync,error));DigitizeJob matte;configure(matte,raw,DigitizeJobKind::Matte);matte.start();CHECK(wait(matte)&&matte.ok&&matte.output&&matte.output->frames[0].rgb==sync.frames[0].rgb&&matte.output->frames[0].alpha==sync.frames[0].alpha&&matte.output->frames[0].source.rgba==raw.frames[0].source.rgba);CHECK(!matte.input->matte_ready&&matte.input->frames[0].source.rgba==raw.frames[0].source.rgba);CHECK(matte.matches(7,11,13)&&!matte.matches(8,11,13)&&!matte.matches(7,12,13)&&!matte.matches(7,11,14));matte.cancel=true;CHECK(!matte.matches(7,11,13));
    DigitizeMaterial material;material.id=1;material.slots=8;sync.materials.push_back(material);CHECK(edit_digitize_mask(sync,0,10,10,1,false,1,error));sync.frames[1].manual=true;sync.frames[1].mask.assign(1024,0);sync.frames[1].mask[10*32+10]=1;sync.allow_unassigned=true;sync.materials[0].tint=true;sync.materials[0].color={24,100,230};auto expected=sync;CHECK(fit_digitize(*art,expected,error));DigitizeJob fit;configure(fit,sync,DigitizeJobKind::Fit);fit.start();CHECK(wait(fit)&&fit.ok&&fit.output&&fit.output->words==expected.words&&fit.output->frames[0].indices==expected.frames[0].indices&&fit.output->frames[1].mask==sync.frames[1].mask&&fit.output->frames[1].manual);CHECK(fit.input->frames[0].indices.empty()&&fit.input->materials[0].reference.r==sync.materials[0].reference.r);ImportBatch batch;CHECK(build_digitize_batch(*art,*fit.output,batch,error)&&art->import_batch(batch,error)>=0);art->undo();
    // The worker receives palette words only: changing the live library cannot alter its result.
    auto matched=sync;matched.palette=0;matched.materials[0].start=1;matched.materials[0].count=8;auto target=copy_palette(*art,0).words;DigitizeJob existing;configure(existing,matched,DigitizeJobKind::Fit);existing.generation=art->generation();existing.target=target;existing.start();art->color(0,1,0x001f);art->commit();CHECK(wait(existing)&&existing.ok&&existing.output->words==target&&!existing.matches(7,art->generation(),13));art->undo();
    DigitizeJob cancelled;configure(cancelled,sync,DigitizeJobKind::Matte);cancelled.cancel=true;cancelled.start();CHECK(wait(cancelled)&&!cancelled.ok&&!cancelled.output&&cancelled.input->frames[0].mask==sync.frames[0].mask&&cancelled.input->materials[0].tint);
    DigitizeJob reseed;configure(reseed,expected,DigitizeJobKind::Reseed);reseed.start();CHECK(wait(reseed)&&reseed.ok&&!reseed.output->frames[1].manual&&reseed.output->frames[0].mask==expected.frames[0].mask&&reseed.input->frames[1].manual);
    // Cancel after a frame completes, before replacement: source/mask data remains intact.
    auto interrupted=sync;auto masks=interrupted.frames[0].mask;DigitizeControl control;bool stop=false;control.cancelled=[&]{return stop;};control.progress=[&](DigitizeStage stage,int done,int){if(stage==DigitizeStage::Matte&&done==1)stop=true;};CHECK(!rebuild_digitize_matte(interrupted,error,control)&&interrupted.frames[0].mask==masks&&interrupted.frames[0].source.rgba==sync.frames[0].source.rgba);
    auto remap=sync;stop=false;control.progress=[&](DigitizeStage stage,int done,int){if(stage==DigitizeStage::Map&&done==1)stop=true;};CHECK(!fit_digitize_palette({},remap,error,control)&&!remap.fitted);
    RampSample population[]={{0,1},{0x7fff,1}};RampColor output[32];int calls=0;CHECK(FitRampLloyd(population,2,32,0,1,100,output,[&]{++calls;return true;})==0&&calls>0);
    DigitizeJob failure;configure(failure,raw,DigitizeJobKind::Fit);failure.start();CHECK(wait(failure)&&!failure.ok&&!failure.output&&!failure.error.empty()&&failure.input->frames[0].source.rgba==raw.frames[0].source.rgba);
    auto root=fs::temp_directory_path()/("digitize-job-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(root);auto file=root/fs::u8path(u8"帧.png");auto pixels=source().rgba;std::vector<unsigned char> encoded;auto sink=[](void *ctx,void *data,int n){auto &out=*(std::vector<unsigned char> *)ctx;out.insert(out.end(),(unsigned char *)data,(unsigned char *)data+n);};CHECK(stbi_write_png_to_func(sink,&encoded,32,32,4,pixels.data(),32*4));{std::ofstream f(file,std::ios::binary);f.write((char *)encoded.data(),encoded.size());}DigitizeJob load;configure(load,{},DigitizeJobKind::Load);load.paths={file.u8string()};load.start();CHECK(wait(load)&&load.ok&&load.output->matte_ready&&load.output->frames[0].source.rgba==pixels&&load.input->frames.empty());
    DigitizeJob bad_load;configure(bad_load,expected,DigitizeJobKind::Load);bad_load.paths={file.u8string(),(root/"missing.png").u8string()};bad_load.start();CHECK(wait(bad_load)&&!bad_load.ok&&!bad_load.output&&bad_load.input->words==expected.words&&bad_load.input->frames[1].mask==expected.frames[1].mask);CHECK(g_doc==nullptr);fs::remove_all(root);return failures?1:0;
}
